const CSS = `
  @import url('https://fonts.googleapis.com/css2?family=DM+Sans:ital,opsz,wght@0,9..40,300;0,9..40,400;0,9..40,500;0,9..40,600;0,9..40,700;1,9..40,400&family=DM+Serif+Display:ital@0;1&display=swap');

  *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

  :root {
    --bg:       #0c1510;
    --surface:  #111a14;
    --surface2: #162019;
    --border:   #1e2e22;
    --border2:  #253229;
    --text:     #e8ede9;
    --muted:    #6b7f70;
    --accent:   #3dd68c;
    --accent2:  #22c55e;
    --gray:     #9ca3af;
    --radius:   14px;
    --transition: 0.2s cubic-bezier(0.4, 0, 0.2, 1);
  }

  html { scroll-behavior: smooth; }
  body {
    font-family: 'DM Sans', sans-serif;
    background: var(--bg);
    color: var(--text);
    -webkit-font-smoothing: antialiased;
    min-height: 100vh;
  }

  /* ── Scrollbar ── */
  ::-webkit-scrollbar { width: 4px; }
  ::-webkit-scrollbar-track { background: transparent; }
  ::-webkit-scrollbar-thumb { background: var(--border2); border-radius: 4px; }

  /* ── Animations ── */
  @keyframes fadeUp {
    from { opacity: 0; transform: translateY(16px); }
    to   { opacity: 1; transform: translateY(0); }
  }
  @keyframes fadeIn {
    from { opacity: 0; }
    to   { opacity: 1; }
  }
  @keyframes spin {
    to { transform: rotate(360deg); }
  }
  @keyframes barGrow {
    from { width: 0%; }
  }
  @keyframes pulse {
    0%, 100% { opacity: 1; }
    50%       { opacity: 0.4; }
  }
  @keyframes recRing {
    0%   { box-shadow: 0 0 0 0 rgba(239,68,68,0.5); }
    70%  { box-shadow: 0 0 0 10px rgba(239,68,68,0); }
    100% { box-shadow: 0 0 0 0 rgba(239,68,68,0); }
  }
  @keyframes shimmer {
    0%   { background-position: -600px 0; }
    100% { background-position: 600px 0; }
  }
  @keyframes dotBlink {
    0%, 80%, 100% { transform: scale(0.6); opacity: 0.4; }
    40%           { transform: scale(1);   opacity: 1;   }
  }
  @keyframes glow {
    0%,100% { opacity: 0.6; }
    50%     { opacity: 1; }
  }

  /* ── Layout ── */
  .ch-root { min-height: 100vh; background: var(--bg); }

  /* ── Top bar ── */
  .ch-topbar {
    position: sticky; top: 0; z-index: 100;
    background: rgba(12, 21, 16, 0.85);
    backdrop-filter: blur(16px);
    border-bottom: 1px solid var(--border);
    display: flex; align-items: center; gap: 10px;
    padding: 0 16px; height: 56px;
  }
  .ch-topbar-logo {
    width: 30px; height: 30px; border-radius: 8px;
    background: linear-gradient(135deg, #22c55e, #16a34a);
    display: flex; align-items: center; justify-content: center;
    color: #fff; flex-shrink: 0;
    box-shadow: 0 2px 8px #22c55e40;
  }
  .ch-topbar-title {
    font-family: 'DM Serif Display', serif;
    font-size: 1rem; color: var(--text); font-weight: 400; flex: 1;
  }
  .ch-topbar-badge {
    font-size: 0.6rem; font-weight: 600; letter-spacing: 0.08em;
    text-transform: uppercase; padding: 3px 8px; border-radius: 20px;
    background: #22c55e18; color: var(--accent); border: 1px solid #22c55e30;
  }

  /* ── Hero ── */
  .ch-hero {
    position: relative; overflow: hidden;
    padding: 32px 16px 28px;
    border-bottom: 1px solid var(--border);
  }
  .ch-hero::before {
    content: '';
    position: absolute; inset: 0;
    background:
      radial-gradient(ellipse 80% 60% at 50% 0%, #22c55e0d 0%, transparent 70%),
      radial-gradient(ellipse 40% 40% at 80% 100%, #3dd68c08 0%, transparent 60%);
    pointer-events: none;
  }
  .ch-hero-grid {
    position: absolute; inset: 0; opacity: 0.04;
    background-image:
      linear-gradient(var(--accent) 1px, transparent 1px),
      linear-gradient(90deg, var(--accent) 1px, transparent 1px);
    background-size: 40px 40px;
    pointer-events: none;
  }
  .ch-hero-inner {
    position: relative; max-width: 600px; margin: 0 auto;
    animation: fadeUp 0.5s ease both;
  }
  .ch-hero-eyebrow {
    display: inline-flex; align-items: center; gap: 6px;
    font-size: 0.65rem; font-weight: 600; letter-spacing: 0.1em;
    text-transform: uppercase; color: var(--accent);
    margin-bottom: 12px;
  }
  .ch-hero-eyebrow-dot {
    width: 5px; height: 5px; border-radius: 50%;
    background: var(--accent); animation: glow 2s ease infinite;
  }
  .ch-hero-h1 {
    font-family: 'DM Serif Display', serif;
    font-size: clamp(1.65rem, 5vw, 2.2rem);
    line-height: 1.15; color: var(--text);
    margin-bottom: 10px; font-weight: 400;
  }
  .ch-hero-h1 em {
    font-style: italic; color: var(--accent);
  }
  .ch-hero-sub {
    font-size: 0.82rem; color: var(--muted); line-height: 1.6;
    max-width: 420px;
  }

  /* ── Body ── */
  .ch-body {
    max-width: 600px; margin: 0 auto;
    padding: 20px 14px 60px;
    display: flex; flex-direction: column; gap: 14px;
  }

  /* ── Card ── */
  .ch-card {
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: var(--radius);
    overflow: hidden;
    animation: fadeUp 0.4s ease both;
    transition: border-color var(--transition), box-shadow var(--transition);
  }
  .ch-card:focus-within {
    border-color: var(--border2);
    box-shadow: 0 0 0 3px #22c55e0c;
  }
  .ch-card-hdr {
    display: flex; align-items: center; gap: 10px;
    padding: 14px 16px 0;
  }
  .ch-card-icon {
    width: 30px; height: 30px; border-radius: 8px; flex-shrink: 0;
