import { useState, useRef, useCallback, useEffect } from 'react';

const API_BASE = 'http://localhost:5001';

// ─── Field metadata ────────────────────────────────────────────────────────────
const FIELD_META = {
  shoot_height_cm:        { label: 'Shoot Height',        unit: 'cm',  icon: 'height'   },
  trunk_circumference_cm: { label: 'Trunk Circumference', unit: 'cm',  icon: 'trunk'    },
  shoot_age_months:       { label: 'Shoot Age',           unit: 'mo',  icon: 'calendar' },
  num_leaves:             { label: 'Leaf Count',          unit: '',    icon: 'leaf'      },
  ccgi_score:             { label: 'CCGI Score',          unit: '',    icon: 'score'     },
  leaf_color:             { label: 'Leaf Colour',         unit: '',    icon: 'palette'   },
  bark_texture:           { label: 'Bark Texture',        unit: '',    icon: 'texture'   },
  bark_color:             { label: 'Bark Colour',         unit: '',    icon: 'palette'   },
  straightness:           { label: 'Straightness',        unit: '',    icon: 'straight'  },
};

// ─── Verdict config ────────────────────────────────────────────────────────────
const VERDICT = {
  'Ready': {
    label: 'Ready for Harvest',
    sub:   'Coppice at 6 cm from ground at a 45° angle for best yield.',
    accent: '#22c55e',
    dim:    '#166534',
    badge:  '#dcfce7',
    badgeText: '#14532d',
    ring:   '0 0 0 1px #22c55e40, 0 8px 32px #22c55e30',
  },
  'Nearly Ready': {
    label: 'Nearly Ready',
    sub:   'Re-assess in 2–4 weeks. Key indicators are improving.',
    accent: '#f59e0b',
    dim:    '#92400e',
    badge:  '#fef3c7',
    badgeText: '#78350f',
    ring:   '0 0 0 1px #f59e0b40, 0 8px 32px #f59e0b25',
  },
  'Not Ready': {
    label: 'Not Ready Yet',
    sub:   'The shoot needs more time to develop. Check again in a month.',
    accent: '#60a5fa',
    dim:    '#1e3a5f',
    badge:  '#dbeafe',
    badgeText: '#1e3a8a',
    ring:   '0 0 0 1px #60a5fa40, 0 8px 32px #60a5fa20',
  },
};

// ─── SVG Icon system ──────────────────────────────────────────────────────────
function Icon({ name, size = 18, className = '' }) {
  const s = { width: size, height: size, display: 'inline-block', flexShrink: 0 };
  const paths = {
    leaf:     <><path d="M11 20A7 7 0 0 1 9.8 6.1C15.5 5 17 4.48 19 2c1 2 2 4.18 2 8 0 5.5-4.78 10-10 10z"/><path d="M2 21c0-3 1.85-5.36 5.08-6C9.5 14.52 12 13 13 12"/></>,
    height:   <><path d="M8 3H5a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h3"/><path d="M16 3h3a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2h-3"/><path d="M12 8v8"/><path d="M9 11l3-3 3 3"/></>,
    trunk:    <><circle cx="12" cy="12" r="4"/><circle cx="12" cy="12" r="9"/></>,
    calendar: <><rect x="3" y="4" width="18" height="18" rx="2"/><path d="M16 2v4M8 2v4M3 10h18"/></>,
    palette:  <><circle cx="13.5" cy="6.5" r=".5"/><circle cx="17.5" cy="10.5" r=".5"/><circle cx="8.5" cy="7.5" r=".5"/><circle cx="6.5" cy="12.5" r=".5"/><path d="M12 2C6.5 2 2 6.5 2 12s4.5 10 10 10c.926 0 1.648-.746 1.648-1.688 0-.437-.18-.835-.437-1.125-.29-.289-.438-.652-.438-1.125a1.64 1.64 0 0 1 1.668-1.668h1.996c3.051 0 5.555-2.503 5.555-5.554C21.965 6.012 17.461 2 12 2z"/></>,
    texture:  <><path d="M4 6h16M4 10h16M4 14h16M4 18h16"/></>,
    straight: <><path d="M12 2v20M2 12h20"/></>,
    score:    <><path d="M12 2l3.09 6.26L22 9.27l-5 4.87 1.18 6.88L12 17.77l-6.18 3.25L7 14.14 2 9.27l6.91-1.01L12 2z"/></>,
    mic:      <><path d="M12 2a3 3 0 0 1 3 3v7a3 3 0 0 1-6 0V5a3 3 0 0 1 3-3z"/><path d="M19 10v2a7 7 0 0 1-14 0v-2"/><path d="M12 19v3M9 22h6"/></>,
    stop:     null,
    search:   <><circle cx="11" cy="11" r="8"/><path d="m21 21-4.35-4.35"/></>,
    check:    <><path d="M22 11.08V12a10 10 0 1 1-5.93-9.14"/><path d="M22 4 12 14.01l-3-3"/></>,
    clock:    <><circle cx="12" cy="12" r="10"/><path d="M12 6v6l4 2"/></>,
    x:        <><circle cx="12" cy="12" r="10"/><path d="m15 9-6 6M9 9l6 6"/></>,
    info:     <><circle cx="12" cy="12" r="10"/><path d="M12 16v-4M12 8h.01"/></>,
    chart:    <><path d="M3 3v18h18"/><path d="M18 9l-5 5-4-4-3 3"/></>,
    eye:      <><path d="M2 12s3-7 10-7 10 7 10 7-3 7-10 7-10-7-10-7z"/><circle cx="12" cy="12" r="3"/></>,
    close:    <><path d="M18 6 6 18M6 6l12 12"/></>,
    sparkle:  <><path d="M9.937 15.5A2 2 0 0 0 8.5 14.063l-6.135-1.582a.5.5 0 0 1 0-.962L8.5 9.936A2 2 0 0 0 9.937 8.5l1.582-6.135a.5.5 0 0 1 .963 0L14.063 8.5A2 2 0 0 0 15.5 9.937l6.135 1.581a.5.5 0 0 1 0 .964L15.5 14.063a2 2 0 0 0-1.437 1.437l-1.582 6.135a.5.5 0 0 1-.963 0z"/></>,
    plant:    <><path d="M7 20h10"/><path d="M10 20c5.5-2.5.8-6.4 3-10"/><path d="M9.5 9.4c1.1.8 1.8 2.2 2.3 3.7-2 .4-3.5.4-4.8-.3-1.2-.6-2.3-1.9-3-4.2 2.8-.5 4.4 0 5.5.8z"/><path d="M14.1 6a7 7 0 0 1 1.5 4.7c-1.7-.1-3.1-.5-4.2-1.4-.9-.8-1.8-2.2-2.4-4.7 2.7-.4 4.2.4 5.1 1.4z"/></>,
  };

  if (name === 'stop') {
    return (
      <svg style={s} className={className} viewBox="0 0 24 24" fill="currentColor">
        <rect x="6" y="6" width="12" height="12" rx="2"/>
      </svg>
    );
  }
  return (
    <svg style={s} className={className} viewBox="0 0 24 24" fill="none"
      stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
      {paths[name]}
    </svg>
  );
}

// ─── Styles ────────────────────────────────────────────────────────────────────
const CSS = `
  @import url('https://fonts.googleapis.com/css2?family=DM+Sans:ital,opsz,wght@0,9..40,300;0,9..40,400;0,9..40,500;0,9..40,600;0,9..40,700;1,9..40,400&family=DM+Serif+Display:ital@0;1&display=swap');

  *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

  :root {
    --bg:       #0c1510;
    --surface:  #111a14;
    --surface2: #162019;
    --border:   #1e2e22;
    --border2:  #253229;
    --text:     #e8ede9;
    --muted:    #6b7f70;
    --accent:   #3dd68c;
    --accent2:  #22c55e;
    --gray:     #9ca3af;
    --radius:   14px;
    --transition: 0.2s cubic-bezier(0.4, 0, 0.2, 1);
  }

  html { scroll-behavior: smooth; }
  body {
    font-family: 'DM Sans', sans-serif;
    background: var(--bg);
    color: var(--text);
    -webkit-font-smoothing: antialiased;
    min-height: 100vh;
  }

  /* ── Scrollbar ── */
  ::-webkit-scrollbar { width: 4px; }
  ::-webkit-scrollbar-track { background: transparent; }
  ::-webkit-scrollbar-thumb { background: var(--border2); border-radius: 4px; }

  /* ── Animations ── */
  @keyframes fadeUp {
    from { opacity: 0; transform: translateY(16px); }
    to   { opacity: 1; transform: translateY(0); }
  }
  @keyframes fadeIn {
    from { opacity: 0; }
    to   { opacity: 1; }
  }
  @keyframes spin {
    to { transform: rotate(360deg); }
  }
  @keyframes barGrow {
    from { width: 0%; }
  }
  @keyframes pulse {
    0%, 100% { opacity: 1; }
    50%       { opacity: 0.4; }
  }
  @keyframes recRing {
    0%   { box-shadow: 0 0 0 0 rgba(239,68,68,0.5); }
    70%  { box-shadow: 0 0 0 10px rgba(239,68,68,0); }
    100% { box-shadow: 0 0 0 0 rgba(239,68,68,0); }
  }
  @keyframes shimmer {
    0%   { background-position: -600px 0; }
    100% { background-position: 600px 0; }
  }
  @keyframes dotBlink {
    0%, 80%, 100% { transform: scale(0.6); opacity: 0.4; }
    40%           { transform: scale(1);   opacity: 1;   }
  }
  @keyframes glow {
    0%,100% { opacity: 0.6; }
    50%     { opacity: 1; }
  }

  /* ── Layout ── */
  .ch-root { min-height: 100vh; background: var(--bg); }

  /* ── Top bar ── */
  .ch-topbar {
    position: sticky; top: 0; z-index: 100;
    background: rgba(12, 21, 16, 0.85);
    backdrop-filter: blur(16px);
    border-bottom: 1px solid var(--border);
    display: flex; align-items: center; gap: 10px;
    padding: 0 16px; height: 56px;
  }
  .ch-topbar-logo {
    width: 30px; height: 30px; border-radius: 8px;
    background: linear-gradient(135deg, #22c55e, #16a34a);
    display: flex; align-items: center; justify-content: center;
    color: #fff; flex-shrink: 0;
    box-shadow: 0 2px 8px #22c55e40;
  }
  .ch-topbar-title {
    font-family: 'DM Serif Display', serif;
    font-size: 1rem; color: var(--text); font-weight: 400; flex: 1;
  }
  .ch-topbar-badge {
    font-size: 0.6rem; font-weight: 600; letter-spacing: 0.08em;
    text-transform: uppercase; padding: 3px 8px; border-radius: 20px;
    background: #22c55e18; color: var(--accent); border: 1px solid #22c55e30;
  }

  /* ── Hero ── */
  .ch-hero {
    position: relative; overflow: hidden;
    padding: 32px 16px 28px;
    border-bottom: 1px solid var(--border);
  }
  .ch-hero::before {
    content: '';
    position: absolute; inset: 0;
    background:
      radial-gradient(ellipse 80% 60% at 50% 0%, #22c55e0d 0%, transparent 70%),
      radial-gradient(ellipse 40% 40% at 80% 100%, #3dd68c08 0%, transparent 60%);
    pointer-events: none;
  }
  .ch-hero-grid {
    position: absolute; inset: 0; opacity: 0.04;
    background-image:
      linear-gradient(var(--accent) 1px, transparent 1px),
      linear-gradient(90deg, var(--accent) 1px, transparent 1px);
    background-size: 40px 40px;
    pointer-events: none;
  }
  .ch-hero-inner {
    position: relative; max-width: 600px; margin: 0 auto;
    animation: fadeUp 0.5s ease both;
  }
  .ch-hero-eyebrow {
    display: inline-flex; align-items: center; gap: 6px;
    font-size: 0.65rem; font-weight: 600; letter-spacing: 0.1em;
    text-transform: uppercase; color: var(--accent);
    margin-bottom: 12px;
  }
  .ch-hero-eyebrow-dot {
    width: 5px; height: 5px; border-radius: 50%;
