    margin-bottom: 10px; font-weight: 400;
  }
  .ch-hero-h1 em {
    font-style: italic; color: var(--accent);
  }
  .ch-hero-sub {
    font-size: 0.82rem; color: var(--muted); line-height: 1.6;
    max-width: 420px;
  }

  /* ── Body ── */
  .ch-body {
    max-width: 600px; margin: 0 auto;
    padding: 20px 14px 60px;
    display: flex; flex-direction: column; gap: 14px;
  }

  /* ── Card ── */
  .ch-card {
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: var(--radius);
    overflow: hidden;
    animation: fadeUp 0.4s ease both;
    transition: border-color var(--transition), box-shadow var(--transition);
  }
  .ch-card:focus-within {
    border-color: var(--border2);
    box-shadow: 0 0 0 3px #22c55e0c;
  }
  .ch-card-hdr {
    display: flex; align-items: center; gap: 10px;
    padding: 14px 16px 0;
  }
  .ch-card-icon {
    width: 30px; height: 30px; border-radius: 8px; flex-shrink: 0;
    background: var(--surface2); border: 1px solid var(--border2);
    display: flex; align-items: center; justify-content:center;
    color: var(--accent);
  }
  .ch-card-label {
    font-size: 0.67rem; font-weight: 600; letter-spacing: 0.09em;
    text-transform: uppercase; color: var(--muted);
  }
  .ch-card-body { padding: 12px 16px 16px; }

  /* ── Textarea ── */
  .ch-ta-wrap { position: relative; }
  .ch-ta {
    width: 100%; min-height: 110px;
    background: var(--surface2); color: var(--text);
    border: 1px solid var(--border2); border-radius: 10px;
    padding: 12px 50px 12px 14px; resize: none; outline: none;
    font-family: 'DM Sans', sans-serif; font-size: 0.9rem; line-height: 1.65;
    transition: border-color var(--transition), box-shadow var(--transition);
  }
  .ch-ta::placeholder { color: var(--muted); font-size: 0.82rem; }
  .ch-ta:focus {
    border-color: #22c55e50;
    box-shadow: 0 0 0 3px #22c55e0c;
  }

  /* ── Mic button ── */
  .ch-mic {
    position: absolute; right: 10px; bottom: 10px;
    width: 34px; height: 34px; border-radius: 50%; border: none; cursor: pointer;
    display: flex; align-items: center; justify-content: center;
    transition: all var(--transition);
  }
  .ch-mic.idle {
    background: var(--surface); border: 1px solid var(--border2); color: var(--muted);
  }
  .ch-mic.idle:hover { border-color: var(--accent); color: var(--accent); }
  .ch-mic.rec {
    background: #ef4444; color: #fff; border: 1px solid #ef4444;
    animation: recRing 1.4s infinite;
  }

  /* ── Hint ── */
  .ch-hint {
    display: flex; align-items: center; gap: 5px;
    font-size: 0.67rem; color: var(--muted); margin-top: 7px;
  }

  /* ── Analyze button ── */
  .ch-btn {
    width: 100%; padding: 13px 16px; margin-top: 12px;
    border: none; border-radius: 10px; cursor: pointer;
    font-family: 'DM Sans', sans-serif; font-size: 0.9rem; font-weight: 600;
    display: flex; align-items: center; justify-content: center; gap: 8px;
    position: relative; overflow: hidden; transition: all var(--transition);
  }
  .ch-btn.on {
    background: linear-gradient(135deg, #22c55e 0%, #16a34a 100%);
    color: #fff;
    box-shadow: 0 4px 20px #22c55e35;
  }
  .ch-btn.on:hover  { transform: translateY(-1px); box-shadow: 0 6px 24px #22c55e45; }
  .ch-btn.on:active { transform: translateY(0); }
  .ch-btn.off {
    background: var(--surface2); color: var(--muted);
    cursor: not-allowed; border: 1px solid var(--border2);
  }
  .ch-btn-shimmer {
    position: absolute; inset: 0;
    background: linear-gradient(90deg, transparent 0%, rgba(255,255,255,0.15) 50%, transparent 100%);
    background-size: 600px 100%;
    animation: shimmer 1.6s infinite;
  }

  /* ── Spinner ── */
  .ch-spin {
    width: 16px; height: 16px; border-radius: 50%;
    border: 2px solid rgba(255,255,255,0.25); border-top-color: #fff;
    animation: spin 0.7s linear infinite;
  }
  .ch-spin-green {
    width: 16px; height: 16px; border-radius: 50%;
    border: 2px solid var(--border2); border-top-color: var(--accent);
    animation: spin 0.7s linear infinite;
  }

  /* ── Loading ── */
  .ch-loading {
    display: flex; align-items: center; gap: 10px;
    background: var(--surface); border: 1px solid var(--border2);
    border-radius: var(--radius); padding: 13px 16px;
    font-size: 0.82rem; color: var(--muted);
    animation: fadeIn 0.25s ease;
  }

  /* ── Error ── */
  .ch-err {
    background: #1a0a0a; border: 1px solid #3d1515;
    border-radius: var(--radius); padding: 14px 16px;
    animation: fadeUp 0.3s ease;
  }
  .ch-err-head {
    display: flex; align-items: center; gap: 7px;
    font-size: 0.8rem; font-weight: 600; color: #f87171;
    margin-bottom: 6px;
  }
  .ch-err-body { font-size: 0.78rem; color: #9a6060; line-height: 1.55; }
  .ch-err-tip  { font-size: 0.72rem; color: #6a4040; margin-top: 5px; }

  /* ── Field pills ── */
  .ch-pills-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(130px, 1fr));
    gap: 8px;
  }
  .ch-pill {
    background: var(--surface2); border: 1px solid var(--border2);
    border-radius: 10px; padding: 10px 12px;
    animation: fadeUp 0.3s ease both;
    transition: border-color var(--transition);
  }
  .ch-pill:hover { border-color: #22c55e40; }
  .ch-pill-label {
    display: flex; align-items: center; gap: 5px;
    font-size: 0.6rem; font-weight: 600; letter-spacing: 0.07em;
    text-transform: uppercase; color: var(--muted); margin-bottom: 4px;
  }
  .ch-pill-label svg { color: var(--accent); opacity: 0.8; }
  .ch-pill-value { font-size: 0.88rem; font-weight: 600; color: var(--text); }

  /* ── Verdict banner ── */
  .ch-verdict {
    border-radius: var(--radius); padding: 20px;
    display: flex; align-items: flex-start; gap: 14px;
    border: 1px solid transparent; animation: fadeUp 0.4s ease;
  }
  .ch-verdict-icon {
    width: 46px; height: 46px; border-radius: 12px; flex-shrink: 0;
    display: flex; align-items: center; justify-content: center;
    background: rgba(255,255,255,0.07);
  }
  .ch-verdict-label {
    font-family: 'DM Serif Display', serif;
    font-size: 1.25rem; font-weight: 400; margin-bottom: 5px;
  }
  .ch-verdict-sub { font-size: 0.76rem; line-height: 1.55; opacity: 0.75; }

  /* ── Confidence bars ── */
  .ch-conf-row {
    display: flex; align-items: center; gap: 10px;
    margin-bottom: 11px;
  }
  .ch-conf-row:last-child { margin-bottom: 0; }
  .ch-conf-name {
    width: 110px; font-size: 0.75rem; color: var(--muted);
    font-weight: 500; flex-shrink: 0;
  }
  .ch-conf-track {
    flex: 1; height: 6px; background: var(--surface2);
    border-radius: 6px; overflow: hidden;
  }
  .ch-conf-fill {
    height: 100%; border-radius: 6px;
    animation: barGrow 0.9s cubic-bezier(0.34, 1.56, 0.64, 1) both;
  }
  .ch-conf-pct {
    width: 36px; text-align: right; font-size: 0.75rem;
    font-weight: 700; font-variant-numeric: tabular-nums;
  }

  /* ── Reasons ── */
  .ch-reasons { display: flex; flex-direction: column; gap: 8px; }
  .ch-reason {
    display: flex; gap: 10px; align-items: flex-start;
    background: var(--surface2); border: 1px solid var(--border2);
    border-radius: 10px; padding: 11px 13px;
    animation: fadeUp 0.35s ease both;
    transition: border-color var(--transition);
  }
  .ch-reason:hover { border-color: #22c55e35; }
  .ch-reason-dot {
    width: 6px; height: 6px; border-radius: 50%;
    background: var(--accent); flex-shrink: 0; margin-top: 7px;
    box-shadow: 0 0 6px var(--accent);
  }
  .ch-reason-text { font-size: 0.81rem; line-height: 1.6; color: #b5c4b9; }

  /* ── Section divider ── */
  .ch-divider {
    display: flex; align-items: center; gap: 10px;
    font-size: 0.6rem; font-weight: 600; letter-spacing: 0.1em;
    text-transform: uppercase; color: var(--muted);
    animation: fadeUp 0.35s ease both;
  }
  .ch-divider::before, .ch-divider::after {
    content: ''; flex: 1; height: 1px; background: var(--border);
  }

  /* ── Footer note ── */
  .ch-footer {
    text-align: center; font-size: 0.68rem; color: var(--muted);
    margin-top: 8px; padding-bottom: 10px; line-height: 1.6;
    animation: fadeUp 0.5s ease both;
  }

  /* ── Responsive: tablet+ ── */
  @media (min-width: 540px) {
    .ch-hero { padding: 40px 24px 36px; }
    .ch-body { padding: 24px 24px 70px; }
    .ch-card-hdr { padding: 16px 20px 0; }
    .ch-card-body { padding: 14px 20px 20px; }
    .ch-ta { font-size: 0.92rem; min-height: 120px; }
    .ch-topbar { padding: 0 24px; }
  }

  @media (min-width: 860px) {
    .ch-hero { padding: 52px 32px 44px; }
    .ch-body { padding: 28px 0 80px; }
  }

  /* ── Mobile fine-tuning ── */
  @media (max-width: 380px) {
    .ch-hero-h1 { font-size: 1.45rem; }
    .ch-pills-grid { grid-template-columns: repeat(2, 1fr); }
    .ch-topbar-badge { display: none; }
  }
`;

function useGlobalCSS() {
  useEffect(() => {
    const id = 'ch-css';
    if (!document.getElementById(id)) {
      const el = document.createElement('style');
      el.id = id; el.textContent = CSS;
      document.head.appendChild(el);
    }
  }, []);
}

// ─── Sub-components ────────────────────────────────────────────────────────────

function TopBar() {
  return (
    <div className="ch-topbar">
      <div className="ch-topbar-logo">
        <Icon name="leaf" size={16} />
      </div>
      <div className="ch-topbar-title">CinnamonHarvest</div>
      <div className="ch-topbar-badge">AI Powered</div>
    </div>
  );
}

function Hero() {
  return (
    <div className="ch-hero">
      <div className="ch-hero-grid" />
      <div className="ch-hero-inner">
        <div className="ch-hero-eyebrow">
          <div className="ch-hero-eyebrow-dot" />
          Ceylon Cinnamon · CCGI Certified
        </div>
        <h1 className="ch-hero-h1">
          Harvest <em>Readiness</em><br />Checker
        </h1>
        <p className="ch-hero-sub">
          Describe a cinnamon shoot in plain language or speak your measurements.
          Our AI model assesses harvest readiness instantly.
        </p>
      </div>
    </div>
  );
}

function InputCard({ text, setText, loading, recording, onToggleVoice, onAnalyze }) {
  return (
    <div className="ch-card">
      <div className="ch-card-hdr">
        <div className="ch-card-icon"><Icon name="sparkle" size={15} /></div>
        <div className="ch-card-label">Shoot Description</div>
      </div>
      <div className="ch-card-body">
        <div className="ch-ta-wrap">
          <textarea
            className="ch-ta"
            value={text}
            onChange={e => setText(e.target.value)}
            onKeyDown={e => {
              if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); onAnalyze(); }
            }}
            placeholder={
              'Type or speak shoot details, e.g.:\n"Height 155 cm, trunk 4.2 cm, age 20 months, dark brown bark, rough and peeling, brownish green leaves, 18 leaves, very straight"'
            }
          />
          <button
            className={`ch-mic ${recording ? 'rec' : 'idle'}`}
            onClick={onToggleVoice}
            title={recording ? 'Stop recording' : 'Speak your measurements'}
          >
            <Icon name={recording ? 'stop' : 'mic'} size={15} />
          </button>
        </div>
        <div className="ch-hint">
          <Icon name="mic" size={11} />
          <span>Tap the mic to speak · Press Enter to analyse</span>
        </div>
        <button
          className={`ch-btn ${loading || !text.trim() ? 'off' : 'on'}`}
          disabled={loading || !text.trim()}
          onClick={onAnalyze}
        >
          {loading && <div className="ch-btn-shimmer" />}
          {loading
            ? <><div className="ch-spin" /> Analysing shoot…</>
            : <><Icon name="search" size={17} /> Check Harvest Readiness</>
          }
        </button>
      </div>
    </div>
  );
}

function LoadingStatus({ msg }) {
  if (!msg) return null;
  return (
    <div className="ch-loading">
      <div className="ch-spin-green" />
      <span>{msg}</span>
    </div>
  );
}

function ErrorCard({ error }) {
  if (!error) return null;
  return (
    <div className="ch-err">
      <div className="ch-err-head">
        <Icon name="x" size={15} /> Connection Error
      </div>
      <div className="ch-err-body">{error}</div>
      <div className="ch-err-tip">Make sure the Flask backend is running at {API_BASE}</div>
    </div>
  );
}

function DetectedFields({ fields }) {
  const entries = Object.entries(fields).filter(([, v]) => v !== null && v !== undefined);
  if (!entries.length) return null;
  return (
    <div className="ch-card" style={{ animationDelay: '0.05s' }}>
      <div className="ch-card-hdr">
        <div className="ch-card-icon"><Icon name="eye" size={15} /></div>
        <div className="ch-card-label">Detected Values</div>
      </div>
      <div className="ch-card-body">
        <div className="ch-pills-grid">
          {entries.map(([k, val], i) => {
            const meta = FIELD_META[k] || { label: k, unit: '', icon: 'info' };
            return (
              <div className="ch-pill" key={k} style={{ animationDelay: `${i * 0.04}s` }}>
                <div className="ch-pill-label">
                  <Icon name={meta.icon} size={10} />
                  {meta.label}
                </div>
                <div className="ch-pill-value">
                  {String(val)}{meta.unit ? ` ${meta.unit}` : ''}
                </div>
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
}

const CONF_BARS = [
  { key: 'Ready',        color: '#22c55e' },
  { key: 'Nearly Ready', color: '#f59e0b' },
  { key: 'Not Ready',    color: '#60a5fa' },
];

const VERDICT_ICON = { 'Ready': 'check', 'Nearly Ready': 'clock', 'Not Ready': 'x' };

function ResultSection({ result }) {
  const v = VERDICT[result.prediction] || VERDICT['Not Ready'];
  return (
    <>
      {/* Verdict */}
      <div
        className="ch-verdict"
        style={{
          background: `linear-gradient(135deg, ${v.accent}12 0%, ${v.accent}06 100%)`,
          borderColor: `${v.accent}30`,
          boxShadow: v.ring,
        }}
      >
        <div className="ch-verdict-icon" style={{ color: v.accent }}>
          <Icon name={VERDICT_ICON[result.prediction] || 'info'} size={22} />
        </div>
        <div>
          <div className="ch-verdict-label" style={{ color: v.accent }}>{v.label}</div>
          <div className="ch-verdict-sub" style={{ color: v.accent }}>{v.sub}</div>
        </div>
      </div>

      {/* Confidence */}
      <div className="ch-card" style={{ animationDelay: '0.08s' }}>
        <div className="ch-card-hdr">
          <div className="ch-card-icon"><Icon name="chart" size={15} /></div>
          <div className="ch-card-label">Confidence Score</div>
        </div>
        <div className="ch-card-body">
          {CONF_BARS.map(({ key, color }) => (
            <div className="ch-conf-row" key={key}>
              <div className="ch-conf-name">{key}</div>
              <div className="ch-conf-track">
                <div
                  className="ch-conf-fill"
                  style={{
                    width: `${result.confidence?.[key] ?? 0}%`,
                    background: color,
                  }}
                />
              </div>
              <div className="ch-conf-pct" style={{ color }}>
                {Math.round(result.confidence?.[key] ?? 0)}%
              </div>
            </div>
          ))}
        </div>
      </div>

      {/* Reasons */}
      <div className="ch-card" style={{ animationDelay: '0.14s' }}>
        <div className="ch-card-hdr">
          <div className="ch-card-icon"><Icon name="info" size={15} /></div>
          <div className="ch-card-label">Analysis Details</div>
        </div>
        <div className="ch-card-body">
          <div className="ch-reasons">
            {result.reasons?.map((r, i) => (
              <div className="ch-reason" key={i} style={{ animationDelay: `${i * 0.07}s` }}>
                <div className="ch-reason-dot" />
                <div className="ch-reason-text">{r}</div>
              </div>
            ))}
          </div>
        </div>
      </div>
    </>
  );
}

// ─── Main component ────────────────────────────────────────────────────────────
export default function CinnamonHarvest() {
  useGlobalCSS();

  const [text, setText]       = useState('');
  const [loading, setLoading] = useState(false);
  const [statusMsg, setMsg]   = useState('');
  const [error, setError]     = useState('');
  const [fields, setFields]   = useState(null);
  const [result, setResult]   = useState(null);
  const [recording, setRec]   = useState(false);

  const recRef    = useRef(null);
  const resultRef = useRef(null);

  const toggleVoice = useCallback(() => {
    const SR = window.SpeechRecognition || window.webkitSpeechRecognition;
    if (!SR) { alert('Voice input is not supported. Please use Chrome or Edge.'); return; }
    if (recording) { recRef.current?.stop(); setRec(false); return; }
    const rec = new SR();
    rec.lang = 'en-US'; rec.interimResults = true; rec.continuous = true;
    recRef.current = rec;
    const base = text;
    rec.onresult = e => {
      let interim = '', final = base;
      for (const r of e.results) {
        if (r.isFinal) final += (final ? ' ' : '') + r[0].transcript;
        else interim = r[0].transcript;
      }
      setText(final + (interim ? ' ' + interim : ''));
    };
    rec.onerror = () => setRec(false);
    rec.onend   = () => setRec(false);
    rec.start();
    setRec(true);
  }, [recording, text]);

  const analyze = useCallback(async () => {
    if (!text.trim() || loading) return;
    setLoading(true); setError(''); setResult(null); setFields(null);
    try {
      setMsg('Reading your description…');
      const pr = await fetch(`${API_BASE}/api/parse`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ text }),
      });
      if (!pr.ok) throw new Error(`Parse failed (${pr.status}): ${await pr.text()}`);
      const parsedFields = (await pr.json()).fields;
      setFields(parsedFields);

      setMsg('Running harvest readiness model…');
      const rr = await fetch(`${API_BASE}/api/predict`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ fields: parsedFields }),
      });
      if (!rr.ok) throw new Error(`Predict failed (${rr.status}): ${await rr.text()}`);
      setResult(await rr.json());
      setMsg('');
      setTimeout(() => resultRef.current?.scrollIntoView({ behavior: 'smooth', block: 'start' }), 120);
    } catch (e) {
      setError(e.message);
      setMsg('');
    } finally {
      setLoading(false);
    }
  }, [text, loading]);

  return (
    <div className="ch-root">
      <TopBar />
      <Hero />
      <div className="ch-body">
        <InputCard
          text={text} setText={setText}
          loading={loading} recording={recording}
          onToggleVoice={toggleVoice} onAnalyze={analyze}
        />

        <LoadingStatus msg={loading ? statusMsg : ''} />
        <ErrorCard error={error} />

        {fields && <DetectedFields fields={fields} />}

        <div ref={resultRef}>
          {result && (
            <>
              <div className="ch-divider" style={{ animationDelay: '0.05s' }}>
                Result
              </div>
              <ResultSection result={result} />
            </>
          )}
        </div>

        <div className="ch-footer">
          Cinnamon Harvest AI · Ceylon Cinnamon Growers Institute data<br />
          For guidance only — confirm with field agronomist before harvest.
        </div>
      </div>
    </div>
  );
}
